const items = $input.all();
const results = [];

const companyData = {
  'stripe.com':     { size: 8000,   industry: 'Fintech',     revenue: '$1B+',          founded: '2010' },
  'notion.so':      { size: 600,    industry: 'SaaS',        revenue: '$100M-$500M',   founded: '2016' },
  'linear.app':     { size: 200,    industry: 'SaaS',        revenue: '$10M-$50M',     founded: '2019' },
  'figma.com':      { size: 1500,   industry: 'SaaS',        revenue: '$500M-$1B',     founded: '2012' },
  'vercel.com':     { size: 500,    industry: 'SaaS',        revenue: '$50M-$100M',    founded: '2015' },
  'supabase.com':   { size: 150,    industry: 'SaaS',        revenue: '$10M-$50M',     founded: '2020' },
  'cloudflare.com': { size: 4000,   industry: 'Tech',        revenue: '$1B+',          founded: '2009' },
  'gitlab.com':     { size: 2200,   industry: 'SaaS',        revenue: '$500M-$1B',     founded: '2011' },
  'hubspot.com':    { size: 7500,   industry: 'SaaS',        revenue: '$1B+',          founded: '2006' },
  'airtable.com':   { size: 800,    industry: 'SaaS',        revenue: '$100M-$500M',   founded: '2012' }
};

const titles = [
  { title: 'VP of Sales',           seniority: 'vp',       dept: 'Sales' },
  { title: 'Director of Marketing', seniority: 'director', dept: 'Marketing' },
  { title: 'Chief Technology Officer', seniority: 'c_suite', dept: 'Engineering' },
  { title: 'Senior Product Manager',seniority: 'senior',   dept: 'Product' },
  { title: 'Head of Operations',    seniority: 'director', dept: 'Operations' },
  { title: 'Marketing Manager',     seniority: 'manager',  dept: 'Marketing' },
  { title: 'VP of Engineering',     seniority: 'vp',       dept: 'Engineering' },
  { title: 'Sales Manager',         seniority: 'manager',  dept: 'Sales' },
  { title: 'Chief Marketing Officer', seniority: 'c_suite', dept: 'Marketing' },
  { title: 'Account Executive',     seniority: 'entry',    dept: 'Sales' }
];

for (const item of items) {
  const trigger = item.json;

  const nameHash = (trigger.first_name + trigger.last_name).split('').reduce((a,c) => a + c.charCodeAt(0), 0);
  const titleData = titles[nameHash % titles.length];

  const company = companyData[trigger.domain] || { 
    size: 250, industry: 'SaaS', revenue: '$10M-$50M', founded: '2017'
  };

  const emailRand = nameHash % 100;
  const emailStatus = emailRand < 80 ? 'valid' : emailRand < 95 ? 'risky' : 'invalid';

  const email = trigger.email && trigger.email.length > 0
    ? trigger.email
    : `${trigger.first_name}.${trigger.last_name}@${trigger.domain}`.toLowerCase();

  results.push({
    json: {
      first_name:       trigger.first_name,
      last_name:        trigger.last_name,
      company:          trigger.company,
      domain:           trigger.domain,
      email:            email,
      email_status:     emailStatus,
      email_confidence: emailStatus === 'valid' ? 92 : emailStatus === 'risky' ? 65 : 20,
      email_disposable: false,
      title:            titleData.title,
      seniority:        titleData.seniority,
      departments:      titleData.dept,
      linkedin_url:     `https://linkedin.com/in/${trigger.first_name}-${trigger.last_name}`.toLowerCase(),
      company_size:     company.size,
      company_revenue:  company.revenue,
      company_industry: company.industry,
      company_founded:  company.founded,
      company_country:  'United States',
      enriched_at: new Date().toISOString()
    }
  });
}

return results;

const items = $input.all();
const enrichedItems = $('Merge Enrichment Data').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const rawResponse = items[i].json;
  const enriched = enrichedItems[i]?.json || {};

  let claudeText = '';
  try {
    claudeText = rawResponse.content?.[0]?.text || '';
  } catch(e) {
    claudeText = '';
  }

  let cleanText = claudeText.trim();

  if (cleanText.startsWith('```')) {
    cleanText = cleanText
      .replace(/^```(?:json)?\s*\n?/i, '')
      .replace(/\n?```\s*$/i, '')
      .trim();
  }

  const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    cleanText = jsonMatch[0];
  }

  let scoring = {};
  try {
    scoring = JSON.parse(cleanText);
  } catch(e) {
    scoring = {
      score:       0,
      tier:        'unknown',
      reasoning:   'Parse error: ' + e.message + ' | Raw: ' + claudeText.substring(0, 150),
      fit_signals: [],
      red_flags:   ['parse_error']
    };
  }

  results.push({
    json: {
      ...enriched,
      score:       parseInt(scoring.score) || 0,
      tier:        scoring.tier  || 'cold',
      reasoning:   scoring.reasoning || '',
      fit_signals: Array.isArray(scoring.fit_signals) ? scoring.fit_signals.join(' | ') : '',
      red_flags:   Array.isArray(scoring.red_flags) ? scoring.red_flags.join(' | ') : '',
      scored_at:   new Date().toISOString()
    }
  });
}

return results;
